	["El izquierdo selecciona y el derecho abre el menú."] = "Le gauche cible et le droit ouvre le menu.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Le gauche cible et le droit ouvre le menu. Vous choisissez le reste.",
	["El izquierdo selecciona y el derecho abre el menú; tu clase no tiene buffs para otros."] = "Le gauche cible et le droit ouvre le menu ; votre classe n'a pas de buffs pour les autres.",
	["El juego aún está cargando este objeto: toca Vincular otra vez en un momento."] = "Le jeu charge encore cet objet : cliquez de nouveau sur Lier dans un instant.",
	["El juego no aceptó la prueba."] = "Le jeu n'a pas accepté le test.",
	["El juego no deja cambiar talentos ahora mismo"] = "Le jeu ne permet pas de changer de talents pour l'instant",
	["El juego no deja enviar mensajes de addon aquí."] = "Le jeu ne permet pas d'envoyer des messages d'addon ici.",
	["El juego no dejó comprar ese rango."] = "Le jeu n'a pas permis d'acheter ce rang.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Le jeu a refusé de confirmer les changements. Ils ont été annulés pour que votre arbre reste comme avant.",
	["El juego todavía no cargó tu árbol."] = "Le jeu n'a pas encore chargé votre arbre.",
	["El juego todavía no cargó tu árbol: se muestra el plan sin tus puntos. Abre la ventana de talentos una vez o espera unos segundos."] = "Le jeu n'a pas encore chargé votre arbre : le plan s'affiche sans vos points. Ouvrez une fois la fenêtre des talents ou attendez quelques secondes.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Le jeu n'a pas encore chargé vos talents. Attendez quelques secondes ou ouvrez une fois la fenêtre des talents (touche N).",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Le mage qui fait le plus de dégâts : sorts de feu et critiques qui brûlent.",
	["El mapa de Alfa"] = "La carte d'Alfa",
	["El mapa del juego no se abre en combate."] = "La carte du jeu ne s'ouvre pas en combat.",
	["El menú de guías, en \"Mis rutas\"."] = "Le menu des guides, dans « Mes itinéraires ».",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "Le menu de la loupe de la carte du jeu contient aussi tous les calques d'Alfa.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "La minicarte passe de ronde à carrée, avec une bordure fine. Déconseillé avec la rotation de la minicarte.",
	["El modelo no lleva nada aquí."] = "Le modèle ne porte rien ici.",
	["El modo prueba se usa fuera de combate."] = "Le mode test s'utilise hors combat.",
	["El motor no aceptó la guía: %s"] = "Le moteur n'a pas accepté le guide : %s",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Le nom de chaque zone sur la carte d'Alfa.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Le nombre en bas à gauche de chaque pièce d'équipement.",
	["El número arriba de cada ícono es el orden en que se toma. Borde verde: ya lo tienes. Borde dorado: falta tomarlo (el más grueso es el siguiente). Borde naranja: puntos fuera del plan."] = "Le nombre au-dessus de chaque icône est l'ordre dans lequel on le prend. Bordure verte : vous l'avez déjà. Bordure dorée : reste à prendre (la plus épaisse est la suivante). Bordure orange : points hors du plan.",
	["El orden importa más que los números: busca piezas con las primeras estadísticas de la lista. Al elegir este build, Alfa usa estos pesos en las flechas de mejora."] = "L'ordre compte plus que les chiffres : cherchez des pièces avec les premières statistiques de la liste. Quand vous choisissez ce build, Alfa utilise ces pondérations pour les flèches d'amélioration.",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Le voleur le plus facile pour monter : il frappe de face, esquive beaucoup et encaisse mieux que les autres.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "La tranche de niveaux de chaque zone, colorée selon votre niveau.",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Le soigneur des chamans : soins en chaîne et totems qui aident tout le groupe.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Le soigneur des druides : vous soignez n'importe quel groupe et survivez bien, même si en solo vous tuez lentement.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Le soigneur des paladins : soins puissants et beaucoup d'armure, idéal en groupe.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Le soigneur pur : gros soins et soins pour tout le groupe.",
	["El sistema de equipo de Alfa no está disponible."] = "Le système d'équipement d'Alfa n'est pas disponible.",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Le tank classique : vous bloquez beaucoup, générez de la menace avec Vengeance et Heurt de bouclier, et avez Dernier rempart quand tout tourne mal.",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Le tank le plus dur à tuer : tous les talents de défense, Mur protecteur amélioré et Dernier rempart tôt. Parfait pour débuter comme tank.",
	["El texto es demasiado largo."] = "Le texte est trop long.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Le texte est arrivé coupé ou modifié : copiez-le à nouveau.",
	["El tipo de nodos que une la ruta."] = "Le type de nœuds que relie l'itinéraire.",
	["El último punto: paras un poco más."] = "Le dernier point : vous parez un peu plus.",
	["Elegir otra guía"] = "Choisir un autre guide",
	["Elegir una guía"] = "Choisir un guide",
	["Elemental"] = "Élémentaire",
	["Elemental para subir"] = "Élémentaire pour monter",
	["Elige el material"] = "Choisissez le matériau",
	["Elige el objeto en el catálogo"] = "Choisissez l'objet dans le catalogue",
	["Elige el objeto en el catálogo y toca \"Agregar a mi ruta\"."] = "Choisissez l'objet dans le catalogue et cliquez sur « Ajouter à mon itinéraire ».",
	["Elige el objeto en el catálogo."] = "Choisissez l'objet dans le catalogue.",
	["Elige la que prefieras"] = "Choisissez celle que vous préférez",
	["Elige qué recolectar y crea la ruta: une los nodos de tu zona en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Choisissez quoi récolter et créez l'itinéraire : il relie les nœuds de votre zone en une boucle courte, la dessine sur la carte, et la flèche vous mène d'arrêt en arrêt.",
	["Elige tu tecla para pescar"] = "Choisissez votre touche de pêche",
	["Elige un objeto de la lista para ver qué es, de dónde sale y para que Alfa te lleve a conseguirlo."] = "Choisissez un objet dans la liste pour voir ce que c'est, d'où il vient, et pour qu'Alfa vous emmène l'obtenir.",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Elle endort tout le groupe puis ressuscite Mograine : c'est normal, pas de panique.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Heurtoir ne réinitialise plus votre attaque : un coup en plus entre deux coups.",
	["Embate sin perder tu ataque automático."] = "Heurtoir sans perdre votre attaque automatique.",
	["Embate sin perder tu ataque."] = "Heurtoir sans perdre votre attaque.",
	["Embate sin perder tu golpe automático."] = "Heurtoir sans perdre votre coup automatique.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Heurtoir sans réinitialiser votre attaque : un coup en plus.",
	["Empezar de nuevo"] = "Recommencer",
	["Empezaste la sesión en el nivel %d."] = "Vous avez commencé la session au niveau %d.",
	["Empezó %s."] = "Commencée %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Commencez de loin avec votre sort le plus lent et finissez avec les instantanés.",
	["Empiezas en nivel %.1f"] = "Vous commencez au niveau %.1f",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "En combat, l'infobulle des personnages et des créatures du monde n'apparaît pas (celle des cadres reste affichée).",
	["En el chat"] = "Dans la discussion",
	["En el mapa"] = "Sur la carte",
	["En el mapa del mundo"] = "Sur la carte du monde",
	["En el marco del objetivo"] = "Sur le cadre de la cible",
	["En el minimapa"] = "Sur la minicarte",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "En groupe, il y a presque toujours plusieurs ennemis : vous en frappez deux à la fois.",
	["En grupo, cura al tanque antes que a nadie."] = "En groupe, soignez le tank avant tout le monde.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "En groupe, soignez d'abord le tank et n'attirez pas de monstres vous-même.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "En groupe, soignez avant que la vie ne baisse trop : ça coûte moins cher.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "En groupe, posez vos totems de mana et de soins près du groupe.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "Dans la grotte du navire, il y a beaucoup de pirates : ne descendez pas tous d'un coup sur le quai.",
	["En la ruta"] = "Dans l'itinéraire",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Dans la deuxième partie, tuez-la en premier : elle soigne beaucoup.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Pour l'hôtel des ventes, il compte le prix le plus bas vu, moins la commission (%d%%, estimée). Pour le désenchantement, il utilise les tables du jeu classique, estimées elles aussi.",
	["En mazmorra"] = "En donjon",
	["En pausa"] = "En pause",
	["En pausa: dentro de una instancia no se comparte nada."] = "En pause : rien n'est partagé à l'intérieur d'une instance.",
	["En pausa: el juego no deja enviar mensajes ahora mismo."] = "En pause : le jeu ne permet pas d'envoyer des messages pour l'instant.",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "Dans les auberges et les villes, vous accumulez de l'XP de repos : vous gagnez le double d'XP par ennemi jusqu'à l'épuiser. Si vous vous déconnectez ici, elle s'accumule aussi.",
	["En qué orden aparecen."] = "L'ordre dans lequel ils apparaissent.",
	["En solitario es lento: usa la varita para rematar."] = "En solo, c'est lent : utilisez la baguette pour achever.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "En solo, posez des soins sur la durée et combattez avec Colère.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "En solo, combattez avec les horions et soignez-vous entre deux monstres.",
	["En tu marco"] = "Sur votre cadre",
	["En un aviso"] = "En alerte",
	["En un aviso y en el chat"] = "En alerte et dans la discussion",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "Sur un vol avec escales, une ligne sous le minuteur indique la prochaine étape et le temps restant pour y arriver. Nécessite le minuteur de vol activé.",
	["En vivo si estás con un banquero; si no, la última foto que guardó Alfa."] = "En direct si vous êtes chez un banquier ; sinon, le dernier relevé enregistré par Alfa.",
	["Encantamiento"] = "Enchantement",
	["Encendido y tecla"] = "Activation et touche",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "Activé : un double-clic pendant la pêche relance la ligne et, avec Maj, Ctrl ou Alt, remonte le poisson. Désactivé : l'inverse.",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Active les changements ci-dessous dans l'infobulle qui s'affiche quand vous survolez un personnage ou une créature.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Active les changements ci-dessous dans la cabine d'essayage (Ctrl + clic sur un objet).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Active les changements ci-dessous ; chacun peut être désactivé séparément. Certains addons placent leurs boutons sur la minicarte carrée après un /reload.",
	["Enciende primero la guía en el minimapa."] = "Activez d'abord le guide sur la minicarte.",
	["Enciende primero los servicios."] = "Activez d'abord les services.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Activez-les ci-dessous, dans Cadres, pour voir la vie de votre groupe et soigner en un clic.",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Immobilisez le monstre et éloignez-vous avant de lancer vos sorts longs.",
	["Entendido"] = "Compris",
	["Entradas de mazmorras"] = "Entrées de donjon",
	["Entradas en el minimapa"] = "Entrées sur la minicarte",
	["Entraste a %s. Consejos y botín: /alfa mazmorras"] = "Vous êtes entré dans %s. Conseils et butin : /alfa mazmorras",
	["Entraste a %s: %d jefes (%d vencidos). Consejos y botín: /alfa mazmorras"] = "Vous êtes entré dans %s : %d boss (%d vaincus). Conseils et butin : /alfa mazmorras",
	["Entrega desconocida"] = "Lieu de remise inconnu",
	["Entregar las completadas"] = "Rendre les quêtes terminées",
	["Entrenador"] = "Maître",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Il empoisonne et lance des éclairs : guérissez le poison si vous le pouvez.",
	["Equilibrada"] = "Équilibrée",
	["Equilibrado"] = "Équilibré",
	["Equilibrio"] = "Équilibre",
	["Equilibrio para subir"] = "Équilibre pour monter",
	["Equipa tu caña de pescar"] = "Équipez votre canne à pêche",
	["Equipo"] = "Équipement",
	["Equipo a punto de romperse."] = "Équipement sur le point de se briser.",
	["Equipo meta para tu nivel"] = "Équipement méta pour votre niveau",
	["Equipo: %d piezas"] = "Équipement : %d pièces",
	["Eres de la manada"] = "Vous faites partie de la meute",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Le donjon est court et se trouve dans Stormwind. Les prisonniers sont dans des cellules de chaque côté : avancez lentement.",
	["Es de una misión."] = "C'est un objet de quête.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "C'est le boss demandé par une quête de l'Alliance : vérifiez vos quêtes avant d'entrer.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "C'est le premier boss, et il est simple. À sa mort, le prisonnier de votre faction ouvre la porte de la cour.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "C'est le dernier du Cimetière. Il lance des flammes autour de lui : si vous combattez à distance, restez loin.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Il est grand et on s'y perd facilement : suivez une seule personne et ne partez pas seul.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "C'est la machine de Sneed : détruisez-la et il sortira se battre.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "C'est le premier donjon de la Horde : court et idéal pour apprendre à jouer en groupe.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "C'est le premier grand donjon de l'Alliance : avancez lentement et attirez un groupe à la fois.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Il est long et a deux entrées. Beaucoup d'ennemis sont en pierre et frappent fort.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Il est long et plein de robots : certains posent des bombes ou déclenchent des alarmes qui font venir plus d'ennemis.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Il est lent : si vous combattez à distance, attaquez-le pendant qu'il approche.",
	["Es muy veloz: frénalo si tu clase puede."] = "Il est très rapide : ralentissez-le si votre classe le peut.",
	["Es raro del Cementerio y no siempre aparece."] = "C'est un rare du Cimetière, il n'apparaît pas toujours.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "C'est un rare du Cimetière, il n'apparaît pas toujours. Il empoisonne : guérissez le poison.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "C'est un rare du Cimetière, il n'apparaît pas toujours. Il peut réduire au silence les lanceurs de sorts.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "C'est un rare qui se montre peu. Il utilise du feu autour de lui.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "C'est un rare, caché dans une grotte. C'est une chauve-souris qui frappe vite.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "C'est un rare, il n'apparaît pas toujours. Il frappe très fort pour son niveau : attirez-le avec prudence.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "C'est un rare, il n'est pas toujours là. Il frappe fort tous ceux qui sont devant lui.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "C'est un rare. Il pose un totem de terre : détruisez-le.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "C'est un rare, il n'est pas toujours là. Il endort les joueurs et explose de magie autour de lui.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Il est simple : bon moment pour boire avant le dernier boss.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "C'est un lanceur de sorts : interrompez-le si votre classe le peut (Coup de pied, Coup de bouclier, Horion de terre...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "C'est un chaman avec des totems : détruisez les totems, ils meurent vite.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "C'est un nain avec un bouclier : il encaisse beaucoup, mais sans surprise.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "C'est un ennemi coriace de la mine : traitez-le comme un petit boss.",
	["Es un grupo: cada uno suelta su propio botín (más abajo, entre los opcionales)."] = "C'est un groupe : chacun laisse tomber son propre butin (plus bas, parmi les boss optionnels).",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "C'est un paladin : il se soigne avec Lumière sacrée. Interrompez son soin.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "C'est un satyre rapide qui empoisonne : si votre classe guérit les poisons, faites-le.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "C'est un trogg qui lance des éclairs : interrompez-le.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "C'est une tortue géante très cuirassée : elle frappe lentement mais fort.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "C'est une tortue très résistante, mais elle ne fait que frapper : aucune surprise.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Cette rangée n'est pas encore ouverte : il manque des points dans cette branche.",
	["Escalas:"] = "Escales :",
	["Escaneando..."] = "Scan en cours...",
	["Escanear ahora"] = "Scanner maintenant",
	["Escanear con Alfa"] = "Scanner avec Alfa",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Scan complet : %s objets avec un prix (%s enchères).",
	["Escarcha"] = "Givre",
	["Escarcha para subir"] = "Givre pour monter",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Masque les barres de nom et les noms des PNJ pendant la pêche (les ennemis hostiles gardent leur nom), pour mieux voir et atteindre le flotteur.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Masque ce qui demande plus de compétence que vous n'en avez. Sans cela, ils s'affichent en gris et pâles.",
	["Escribe el nombre debajo del ícono: útil mientras aprendes."] = "Écrit le nom sous l'icône : utile pendant l'apprentissage.",
	["Escribe en el chat los sonidos de tu lista."] = "Affiche dans la fenêtre de discussion les sons de votre liste.",
	["Escribe un nombre corto para reconocerla."] = "Tapez un nom court pour le reconnaître.",
	["Escribir a %s"] = "Écrire à %s",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Bouclier et défense : vous retenez tous les monstres pour que votre groupe ne souffre pas.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Bouclier et lumière sacrée : un tank très résistant qui récupère son propre mana.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Boucliers et soins préventifs : vous encaissez beaucoup et soutenez le groupe.",
	["Ese build es para otra clase."] = "Ce build est pour une autre classe.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Ce talent exige d'abord un autre talent complet (la flèche de l'arbre).",
	["Ese texto es demasiado largo para un build."] = "Ce texte est trop long pour un build.",
	["Ese texto no es una ruta de Alfa."] = "Ce texte n'est pas un itinéraire d'Alfa.",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Ce n'est pas une chaîne de build d'Alfa. Elle commence par ALFA1;",
	["Espacio libre"] = "Espace libre",
	["Espadas"] = "Épées",
	["Espalda"] = "Dos",
	["Espera %s"] = "Attendez %s",
	["Espera a entrar al mundo."] = "Attendez d'être dans le monde.",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "Attendez que le tank ait bien l'ennemi en main avant de frapper fort.",
	["Espera a salir de combate para probarla."] = "Attendez d'être hors combat pour la tester.",
	["Espera a salir de combate."] = "Attendez d'être hors combat.",
	["Espíritu"] = "Esprit",
	["Esquiva (%)"] = "Esquive (%)",
	["Esquivar"] = "Esquive",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Cette classe n'a pas de pondérations de statistiques dans Alfa.",
	["Esta clase no tiene pesos de estadísticas."] = "Cette classe n'a pas de pondérations de statistiques.",
	["Esta mazmorra no tiene jefes en el diario."] = "Ce donjon n'a pas de boss dans le journal.",
	["Esta sesión, por recurso"] = "Cette session, par ressource",
	["Esta sesión: %s"] = "Cette session : %s",
	["Esta subasta no permite el escaneo completo."] = "Cet hôtel des ventes ne permet pas le scan complet.",
	["Estado"] = "État",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Ce build frappe extrêmement fort, mais encaisse peu : choisissez bien le moment d'entrer.",
	["Este cliente no da el arte del mapa: no se puede dibujar el mapa continuo."] = "Ce client ne fournit pas l'illustration de la carte : impossible de dessiner la carte continue.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Ce client ne peut pas copier votre configuration tout seul : la fenêtre de lancement par clic de Blizzard s'est ouverte pour que vous la fassiez là.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Ce client n'a pas le lancement par clic de Blizzard. Vos clics fonctionnent sur les cadres d'Alfa.",
	["Este personaje: %s en total"] = "Ce personnage : %s au total",
	["Este tramo quedó vacío."] = "Ce tronçon est vide.",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Impossible de changer cela en combat. Réessayez à la fin du combat.",
	["Estos talentos no están en tu árbol (quizás cambiaron con un parche) y se saltan: %s."] = "Ces talents ne sont pas dans votre arbre (un patch les a peut-être changés) et sont ignorés : %s.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Il est dans le Cimetière. Il inflige une douleur de l'ombre qui fait des dégâts sur la durée.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Il est dans l'eau, près de la cascade : amenez-le sur la terre ferme avant de combattre.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Il est dans l'Armurerie. Quand il crie, il tournoie avec sa hache et frappe tous ceux qui sont proches : éloignez-vous.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Il est dans la Bibliothèque et arrive avec ses chiens : tuez-les d'abord ou utilisez des attaques de zone.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Il est caché dans la Cathédrale. Il lance des malédictions et se soigne : interrompez-le.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Il est plein de hurans et de tunnels d'épines : attirez-en peu à la fois.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Il est entouré de gobelins au travail : attirez d'abord ces gobelins, un par un.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Il est entouré de murlocs : attirez ses amis avant lui.",
	["Estás descansando"] = "Vous êtes au repos",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Vous êtes en combat. Les talents ne se changent que hors combat : finissez le combat et réessayez.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Vous êtes en combat : cherchez l'équipement à la fin du combat.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Vous êtes en combat : vos changements s'appliqueront à la sortie du combat.",
	["Evento"] = "Événement",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "Évite les coups critiques et écrasants : le plus important pour un tank.",
	["Evitar misiones de grupo (élites)"] = "Éviter les quêtes de groupe (élites)",
	["Explicar por qué"] = "Expliquer pourquoi",
	["Fallas menos golpes, sobre todo contra monstruos de nivel más alto que el tuyo."] = "Vous ratez moins de coups, surtout contre les monstres de niveau supérieur au vôtre.",
	["Fallas menos golpes."] = "Vous ratez moins de coups.",
	["Fallas menos: con dos armas fallas mucho sin esto."] = "Vous ratez moins : avec deux armes, vous ratez beaucoup sans cela.",
	["Fallida"] = "Échouée",
	["Fallidas, grises (ya no dan XP) o muy lejos: las marca para abandonar. Las de grupo o mazmorra quedan fuera de la ruta."] = "Échouées, grises (elles ne donnent plus d'XP) ou très loin : il les coche pour les abandonner. Celles de groupe ou de donjon restent hors de l'itinéraire.",
	["Falta el final del texto: cópialo completo."] = "La fin du texte manque : copiez-le en entier.",
	["Falta la carpeta Alfa_Codex: reinstala Alfa."] = "Le dossier Alfa_Codex est manquant : réinstallez Alfa.",
	["Faltan las texturas de detalle en la carpeta Media de Alfa_Mundo: el mapa se dibuja solo con el arte del juego."] = "Les textures de détail manquent dans le dossier Media d'Alfa_Mundo : la carte est dessinée uniquement avec l'illustration du jeu.",
	["Faltan precios de algunos materiales."] = "Il manque le prix de certains matériaux.",
	["Faltan precios de sus materiales: escanea la subasta."] = "Il manque le prix de ses matériaux : scannez l'hôtel des ventes.",
	["Fantasma"] = "Fantôme",
	["Fijada: Alfa no la cambia al recalcular."] = "Épinglée : Alfa ne la change pas en recalculant.",
	["Fijar en este tramo"] = "Épingler dans ce tronçon",
	["Fijar marcos"] = "Verrouiller les cadres",
	["Filones y depósitos de mineral."] = "Filons et gisements de minerai.",
	["Fin de tu ruta. Arma la siguiente en /alfa rutas."] = "Fin de votre itinéraire. Construisez le suivant avec /alfa rutas.",
	["Flecha de mejora"] = "Flèche d'amélioration",
	["Forever ya trae avisos de jefes hechos por Blizzard: una línea de tiempo con los ataques que vienen y mensajes grandes cuando algo es peligroso. Alfa no inventa avisos propios: aquí los prendes y los ajustas, explicados en sencillo."] = "Forever inclut déjà des alertes de boss faites par Blizzard : une chronologie des attaques à venir et de grands messages quand quelque chose est dangereux. Alfa n'invente pas ses propres alertes : ici, vous les activez et les réglez, expliquées simplement.",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "Forme de félin pour tuer vite et forme d'ours pour les combats difficiles ; vous n'avez presque jamais besoin de boire.",
	["Foto: %s"] = "Relevé : %s",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "Ralentit ceux qui fuient et vous permet d'échapper à un mauvais combat.",
	["Frena a los que huyen y te salva de malas peleas."] = "Ralentit ceux qui fuient et vous sauve des mauvais combats.",
	["Frena a todos los rivales cercanos."] = "Ralentit tous les adversaires proches.",
	["Fuego"] = "Feu",
	["Fuego para subir"] = "Feu pour monter",
	["Fuera de combate es el mejor momento"] = "Hors combat, c'est le meilleur moment",
	["Fuera de esta ruta: %s (%s)."] = "Hors de cet itinéraire : %s (%s).",
	["Fuerza"] = "Force",
	["Furia"] = "Fureur",
	["Furia con dos armas"] = "Fureur à deux armes",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "Fureur avec tous les dégâts possibles : plus de toucher, Exécution améliorée et critiques énormes. Très rapide pour tuer, mais fragile.",
	["Furia contra jugadores"] = "Fureur JcJ",
	["Furia desatada"] = "Fureur déchaînée",
	["Furia para grupo"] = "Fureur en groupe",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "Fureur pour combattre les joueurs : énormément de dégâts, Rage berserker améliorée contre la peur et Interception plus souvent pour ne pas lâcher l'adversaire.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "Rage sanguinaire vous donne plus de rage pour commencer les combats difficiles.",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "Gagnez un peu d'XP et Alfa calculera ce qu'il vous reste.",
	["Ganado"] = "Gagné",
	["Ganas de más"] = "Or en plus",
	["Gasta la ira sobrante en Golpe heroico; si llegas a 100 de ira, la estás desperdiciando."] = "Dépensez la rage en trop dans Frappe héroïque ; si vous atteignez 100 de rage, vous la gaspillez.",
	["Gastado"] = "Dépensé",
	["Golpe (%)"] = "Toucher (%)",
	["Golpe con hechizos (%)"] = "Toucher des sorts (%)",
	["Golpe crítico"] = "Coup critique",
	["Golpe crítico (%)"] = "Coup critique (%)",
	["Golpe fuerte que además reduce las curas del rival."] = "Une frappe puissante qui réduit aussi les soins de l'adversaire.",
	["Golpe heroico cuesta menos ira: lo usarás en cada pelea."] = "Frappe héroïque coûte moins de rage : vous l'utiliserez à chaque combat.",
	["Golpe heroico más barato."] = "Frappe héroïque moins chère.",
	["Golpe heroico más barato: amenaza extra con la ira que sobra."] = "Frappe héroïque moins chère : menace en plus avec la rage en trop.",
	["Golpe heroico más barato: la ira sobrante se vuelve amenaza."] = "Frappe héroïque moins chère : la rage en trop devient de la menace.",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "Il frappe ceux qui l'entourent : tournez-le loin du groupe.",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "Il frappe tous ceux qui sont proches et les repousse : si vous combattez au corps à corps, surveillez votre vie.",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "Il frappe tous ceux qui sont devant lui : attaquez de dos si vous combattez au corps à corps.",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "Il frappe tous ceux qui sont devant lui : au corps à corps, attaquez par derrière.",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "Il frappe fort avec son couperet et provoque des saignements : surveillez la vie du tank.",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "Il frappe et repousse le tank : revenez vite à votre place.",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "Vous frappez deux ennemis à la fois : vous pouvez attirer les monstres deux par deux.",
	["Gran aumento de daño para los jefes."] = "Gros bonus de dégâts pour les boss.",
	["Gran aumento de daño y te libra del miedo."] = "Gros bonus de dégâts, et vous libère de la peur.",
	["Gran aumento de daño."] = "Gros bonus de dégâts.",
	["Gran golpe de escudo con mucha amenaza."] = "Un grand coup de bouclier avec beaucoup de menace.",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "Cri de guerre pour le guerrier ; Intelligence des Arcanes et une armure pour le mage ; Robustesse et Feu intérieur pour le prêtre ; et ce qu'il faut pour chaque classe.",
	["Grupo"] = "Groupe",
	["Grupo de %d"] = "Groupe de %d",
	["Guarda Grito intimidador para cuando estés en peligro."] = "Gardez Cri d'intimidation pour quand vous êtes en danger.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "Gardez Mur protecteur pour les pires moments du boss.",
	["Guardar"] = "Garder",
	["Guardas ira al cambiar de actitud."] = "Vous gardez de la rage en changeant de posture.",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "Vous gardez votre rage en changeant de posture : Charge, Fulgurance et Vengeance sont presque gratuites.",
	["Guerrero"] = "Guerrier",
	["Guiarme"] = "Me guider",
	["Guía"] = "Guide",
	["Guía abierta: %s. Sigue la flecha."] = "Guide ouvert : %s. Suivez la flèche.",
