	["Ligado: no se subasta"] = "Lié : ne peut pas être mis aux enchères",
	["Limpiar"] = "Vider",
	["Limpien a sus ayudantes antes de empezar con él."] = "Éliminez ses aides avant de vous occuper de lui.",
	["Lista para entregar"] = "Prête à rendre",
	["Listo"] = "Terminé",
	["Listo para ayudar a tu grupo"] = "Prêt à aider votre groupe",
