	["Manos"] = "Mains",
	["Mantén Furia recta encendida cuando tanquees."] = "Gardez Fureur vertueuse active quand vous tankez.",
	["Mantén Grito de batalla siempre puesto."] = "Gardez Cri de guerre actif en permanence.",
	["Mantén Seccionar en el rival para que no huya."] = "Gardez Brise-genou sur l'adversaire pour qu'il ne fuie pas.",
	["Mantén al monstruo lejos: tu mascota lo detiene mientras disparas."] = "Gardez le monstre à distance : votre familier le retient pendant que vous tirez.",
	["Maná"] = "Mana",
