	["Para abandonar"] = "À abandonner",
	["Para alguien de tu hermandad, agrega su rango."] = "Pour un membre de votre guilde, ajoute son rang.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Pour chaque objet, Alfa compare trois options : le vendre au marchand, le mettre aux enchères ou le transformer (avec une recette que vous connaissez ou en le désenchantant).",
	["Para mi nivel (±3)"] = "Pour mon niveau (±3)",
	["Para mover la línea de tiempo o los mensajes: abre el menú del juego (Esc) y elige %s."] = "Pour déplacer la chronologie ou les messages : ouvrez le menu du jeu (Échap) et choisissez %s.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Pour ne pas voir votre groupe en double. Se change hors combat.",
	["Para pescar necesitas una caña en las manos. Cuando la tengas puesta, ya puedes lanzar."] = "Pour pêcher, il vous faut une canne à pêche en main. Une fois équipée, vous pouvez lancer.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Pour éviter les conflits, Alfa ne prend pas votre touche et ne modifie pas vos réglages. Désactivez l'un des deux dans la liste des addons (écran de sélection des personnages) et rechargez. Si vous gardez Alfa, il reprendra tout seul la touche que vous utilisiez dans l'autre addon.",
	["Para que no dejes botín tirado por falta de espacio."] = "Pour ne jamais laisser de butin faute de place.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Pour ceux qui préfèrent cibler au clic gauche : le soin de ce clic passe au bouton central. Votre préréglage est réappliqué.",
	["Para quien ya jugó esta mazmorra antes de instalar Alfa."] = "Pour ceux qui ont fait ce donjon avant d'installer Alfa.",
	["Para subir de nivel"] = "Avant le prochain niveau",
	["Para tu nivel"] = "Pour votre niveau",
	["Para una montura mira el Buscador: dice qué nivel, equitación y oro pide."] = "Pour une monture, consultez Recherche : elle indique le niveau, la monte et l'or nécessaires.",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "Pour en accumuler à nouveau, reposez-vous (ou déconnectez-vous) dans une auberge ou une ville.",
	["Parada (%)"] = "Parade (%)",
	["Parar"] = "Parade",
	["Paras más golpes de otros guerreros y pícaros."] = "Vous parez plus de coups des autres guerriers et des voleurs.",
	["Paras más golpes."] = "Vous parez plus de coups.",
	["Paras más golpes: recibes menos daño desde el principio."] = "Vous parez plus de coups : vous subissez moins de dégâts dès le début.",
	["Paras un poco más."] = "Vous parez un peu plus.",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "Vous avez paré un coup : votre contre-attaque immobilise l'ennemi.",
	["Paraste un golpe: tu talento de contraataque está listo y desarma al enemigo."] = "Vous avez paré un coup : votre talent de contre-attaque est prêt et désarme l'ennemi.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "Survolez un membre du groupe et cliquez : le gauche %s et le droit %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "Il transmet des maladies : guérissez-les si votre classe le peut.",
