	["Pecho"] = "Torse",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Collez ici (Ctrl+V) le texte d'un itinéraire d'Alfa.",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "Collez ici une chaîne qui commence par ALFA1; (Ctrl + V) et appuyez sur Importer. Alfa vérifie chaque talent dans votre arbre.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "Il frappe fort mais sans surprise : c'est un bon boss pour apprendre.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "Il frappe fort et se protège avec un bouclier de lumière : commencez avec toute votre vie.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "Il frappe le tank de nombreuses fois de suite : ne laissez pas sa vie passer sous la moitié.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "Il frappe très fort : commencez le combat avec toute votre vie.",
	["Pega primero una cadena de build de Alfa."] = "Collez d'abord une chaîne de build d'Alfa.",
	["Pega varias veces seguidas: empieza con la vida llena."] = "Il frappe plusieurs fois de suite : commencez avec toute votre vie.",
	["Pegas a dos: útil contra mascotas y grupos."] = "Vous frappez deux cibles : utile contre les familiers et les groupes.",
	["Pegas más después de recibir críticos."] = "Vous frappez plus fort après avoir subi des critiques.",
	["Pegas más fuerte después de recibir críticos."] = "Vous frappez plus fort après avoir subi des critiques.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "Vous frappez plus fort après avoir subi un coup critique.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "Combattez un seul monstre à la fois ; si deux arrivent, utilisez Attaques circulaires.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "Combattez toujours avec toute votre vie ; n'enchaînez pas les monstres sans vous reposer.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "Combattre d'autres joueurs : encaisser, ralentir et achever.",
	["Peletería"] = "Travail du cuir",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "Le Travail du cuir fabrique du cuir avec armure et endurance pour la forme d'ours.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "Le Travail du cuir fabrique des mailles pour vous ; le Dépeçage vous fournit les matériaux sans dépenser d'or.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "Le Travail du cuir fabrique des pièces de cuir avec agilité et endurance ; le Dépeçage vous fournit le cuir.",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "De petites icônes sur chaque attaque : si elle vise le tank ou le soigneur, si elle peut être dissipée ou si elle est mortelle.",
