	["Se agregó el sonido %d a tu lista."] = "Son %d ajouté à votre liste.",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "La progression des donjons de ce personnage est effacée. Impossible d'annuler.",
	["Se borra lo pescado en esta sesión. Tu habilidad de pesca no cambia."] = "Les prises de cette session sont effacées. Votre compétence de pêche ne change pas.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "Les sessions enregistrées de ce personnage sont effacées. La session en cours continue de compter.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "Les sessions, les zones et les objets de ce personnage sont effacés. Impossible d'annuler.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "Les boss vaincus, le nombre de fois terminé et le butin noté de %s sont effacés pour ce personnage.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "Les prix enregistrés de l'hôtel des ventes pour ce royaume et cette faction sont effacés. Vos recettes restent.",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "L'hôtel des ventes s'est fermé avant de recevoir les prix. Réessayez plus tard.",
	["Se cura a sí mismo: interrumpe su curación."] = "Il se soigne : interrompez son soin.",
	["Se cura comiendo: mátenlo rápido."] = "Il se soigne en mangeant : tuez-le vite.",
	["Se cura: interrúmpelo."] = "Il se soigne : interrompez-le.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, abajo de la página puedes olvidar tu progreso aquí."] = "Tous les boss de %s sont découverts, comme si vous l'aviez terminé. En cas d'erreur, vous pouvez oublier votre progression ici, en bas de la page.",
	["Se enfurece al final: guarden su mejor daño."] = "Il devient enragé à la fin : gardez vos meilleurs dégâts.",
	["Se enfurece con poca vida: termínenlo rápido."] = "Il devient enragé quand sa vie est basse : achevez-le vite.",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "Il s'énerve et frappe de plus en plus fort : tuez-le vite.",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "Le combat a lieu sous l'eau : surveillez votre barre de respiration et remontez prendre de l'air si besoin.",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "Il se protège avec son bouclier et étourdit : attaquez d'abord les deux autres.",
	["Se puede enviar ahora: %s"] = "Envoi possible maintenant : %s",
	["Se pusieron %d de %d opciones; las demás el juego no las dejó cambiar."] = "%d options sur %d ont été appliquées ; le jeu n'a pas permis de changer les autres.",
	["Se queda en el modo limpio."] = "Reste en mode épuré.",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "Il est retiré de votre liste. Si vous en avez de nouveau besoin, réimportez sa chaîne.",
