	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "Aussi celles qui ne viennent pas du guide (« Accepter les quêtes du guide » s'occupe de celles-là). Les quêtes grises sont ignorées, celles qui demandent de l'or, des monnaies ou des matériaux d'artisanat ne sont pas rendues, et s'il y a plusieurs récompenses, c'est vous qui choisissez. Maintenez Maj enfoncée pour le faire vous-même.",
	["También puedes lanzar con doble clic derecho."] = "Vous pouvez aussi lancer par double-clic droit.",
	["Tanque"] = "Tank",
	["Tanque de amenaza"] = "Tank de menace",
	["Tanque de escudo"] = "Tank bouclier",
	["Tanque muralla"] = "Tank rempart",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "Fiche des nouvelles compétences à chaque niveau",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "Nous avons ouvert un chuchotement pour %s avec votre message. Vérifiez-le et appuyez sur Entrée pour l'envoyer.",
	["Te ayuda a armar tu personaje aunque no sepas por dónde empezar: talentos, estadísticas, equipo y profesiones, con el porqué de cada cosa."] = "Vous aide à construire votre personnage même si vous ne savez pas par où commencer : talents, statistiques, équipement et métiers, avec le pourquoi de chaque chose.",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "Vous donne de la puissance d'attaque : chaque coup frappe plus fort. Pour le guerrier, elle augmente aussi le blocage au bouclier.",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "Vous indique quelle pièce va se briser, pour la réparer à temps.",
	["Te falta %s"] = "Il vous manque %s",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "Encore %s XP avant le niveau %d, à votre rythme actuel.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "Il vous manque des niveaux : chaque niveau à partir du 10 vous donne un point.",
	["Te queda 1 espacio"] = "Il vous reste 1 emplacement",
	["Te queda poca XP descansada"] = "Il vous reste peu d'XP de repos",
	["Te quedan %d de %d espacios"] = "Il vous reste %d emplacements sur %d",
	["Tecla para pescar"] = "Touche de pêche",
	["Tecla: %s"] = "Touche : %s",
	["Temporizador de golpe"] = "Minuteur de coup",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "Ayez toujours une potion de soins sous la main : ce build ne pardonne pas les erreurs.",
	["Tesoros"] = "Trésors",
	["Tesoros en el mapa"] = "Trésors sur la carte",
	["Tesoros en el minimapa"] = "Trésors sur la minicarte",
	["Tiempo"] = "Temps",
	["Tiempo de juego por sesión"] = "Temps de jeu par session",
	["Tiempo de sesión"] = "Durée de la session",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "Délai maximal entre les deux clics. Augmentez-le si vos doubles-clics ne lancent pas la ligne.",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "Il a quatre parties qui se font séparément : Cimetière, Bibliothèque, Armurerie et Cathédrale, de la plus facile à la plus difficile.",
	["Tienes"] = "Vous avez",
	["Tienes %d"] = "Vous en avez %d",
	["Tienes %d puntos de talento."] = "Vous avez %d points de talent.",
	["Tienes %d · en %s"] = "Vous en avez %d · dans %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "Vous avez %s prix issus de vos recherches. Pour tous les connaître, scannez à l'hôtel des ventes.",
	["Tienes 6 guías abiertas: cierra una pestaña para abrir la ruta."] = "Vous avez 6 guides ouverts : fermez un onglet pour ouvrir l'itinéraire.",
	["Tienes 6 guías abiertas: cierra una pestaña para abrir otra."] = "Vous avez 6 guides ouverts : fermez un onglet pour en ouvrir un autre.",
	["Tienes 6 guías abiertas: cierra una pestaña para abrir tu ruta."] = "Vous avez 6 guides ouverts : fermez un onglet pour ouvrir votre itinéraire.",
	["Tienes activado \"Rechazar invitaciones de hermandad\" en Comodidades: apágalo para que te llegue la invitación."] = "« Refuser les invitations de guilde » est activé dans Confort de jeu : désactivez-le pour recevoir l'invitation.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "Vous avez des changements non confirmés dans la fenêtre des talents : ils sont annulés avant l'application.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "Vous avez de la rage : utilisez-le avant le prochain combat, il vous donne, à vous et à votre groupe, plus de puissance d'attaque.",
	["Tienes habilidades nuevas"] = "Vous avez de nouvelles compétences",
	["Tienes más rangos de los que pide el build"] = "Vous avez plus de rangs que ce que demande le build",
	["Tienes otro addon de bolsas activo: mientras lo esté, Alfa no reemplaza tus bolsas. Igual puedes abrir la ventana de Alfa desde aquí."] = "Un autre addon de sacs est activé : tant qu'il l'est, Alfa ne remplace pas vos sacs. Vous pouvez quand même ouvrir la fenêtre d'Alfa d'ici.",
	["Tienes puntos fuera del plan en: %s. Alfa no quita talentos: para seguir el build exacto, reinicia tus talentos con tu entrenador de clase."] = "Vous avez des points hors du plan dans : %s. Alfa ne retire pas de talents : pour suivre le build à la lettre, réinitialisez vos talents auprès de votre maître de classe.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "Vous avez des points hors du plan : Alfa ne les retire pas, il ne fait qu'ajouter.",
	["Tienes un punto de talento."] = "Vous avez un point de talent.",
	["Tipo"] = "Type",
	["Toca para ver de dónde sale"] = "Cliquez pour voir d'où il vient",
	["Toda la cuenta"] = "Tout le compte",
	["Todas"] = "Tous",
	["Todas las mazmorras"] = "Tous les donjons",
	["Todas las misiones"] = "Toutes les quêtes",
	["Todas sus fuentes en el Buscador de Alfa."] = "Toutes ses sources dans la Recherche d'Alfa.",
	["Todas tus misiones abiertas, para completarlas y entregarlas por el camino más corto."] = "Toutes vos quêtes en cours, à terminer et rendre par le chemin le plus court.",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "Vous ne connaissez pas encore ses sorts : ils se remplissent à mesure que vous les apprenez.",
	["Todavía no gastas puntos de talento"] = "Vous n'avez pas encore dépensé de points de talent",
	["Todavía no has pescado nada en esta sesión. Lo que saques aparece aquí, con cuántos llevas de cada uno."] = "Vous n'avez encore rien pêché pendant cette session. Vos prises s'affichent ici, avec le nombre de chacune.",
	["Todavía no has vencido a ningún jefe. ¡Tu primera mazmorra te espera!"] = "Vous n'avez encore vaincu aucun boss. Votre premier donjon vous attend !",
	["Todavía no hay builds de este tipo para tu clase: Alfa te muestra el más parecido."] = "Il n'y a pas encore de builds de ce type pour votre classe : Alfa vous montre le plus proche.",
	["Todavía no hay consejos para este jefe."] = "Pas encore de conseils pour ce boss.",
	["Todavía no hay datos de este personaje. Entra al juego con él una vez."] = "Pas encore de données pour ce personnage. Connectez-vous une fois avec lui.",
	["Todavía no hay datos para esta gráfica."] = "Pas encore de données pour ce graphique.",
	["Todavía no hay foto de este banco. Visita a un banquero con ese personaje y Alfa la guardará."] = "Pas encore de relevé de cette banque. Allez voir un banquier avec ce personnage et Alfa l'enregistrera.",
	["Todavía no importaste ninguno."] = "Vous n'en avez encore importé aucun.",
	["Todavía no lo recolectas"] = "Pas encore récolté",
	["Todavía no recolectas nada en esta sesión. Mina, herboriza, pesca en un banco o abre un cofre y aparece aquí."] = "Rien récolté pendant cette session. Minez, cueillez des herbes, pêchez dans un banc ou ouvrez un coffre, et ça apparaîtra ici.",
	["Todavía no sabes pescar"] = "Vous ne savez pas encore pêcher",
	["Todavía no tienes talentos para exportar."] = "Vous n'avez pas encore de talents à exporter.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "Vous n'avez pas encore de guide ouvert. Choisissez-en un et Alfa vous guide pas à pas : où aller, quoi faire et à qui parler.",
	["Todo bien (lo más gastado: %d%%)"] = "Tout va bien (le plus usé : %d%%)",
	["Todo el botín"] = "Tout le butin",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Tout pour les dégâts : critiques, saignements et Fulgurance très souvent. Vous tuez à toute vitesse, mais sans défense en plus : si beaucoup d'ennemis s'en prennent à vous, fuyez.",
	["Todos"] = "Tous",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Tous ceux de ce type, ou un seul (par exemple, seulement le cuivre). Entre parenthèses, combien il y en a dans votre zone.",
	["Todos los objetos del juego: busca, filtra y consíguelos."] = "Tous les objets du jeu : cherchez, filtrez et obtenez-les.",
	["Todos los tipos"] = "Tous les types",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Tous vos points sont déjà dépensés, dont une partie hors de ce build. Pour passer à ce build, réinitialisez vos talents auprès de votre maître de classe ; ensuite, Alfa vous les applique en un clic.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Tous : les alertes mineures aussi. Seulement les graves : uniquement ce qui peut vous tuer.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Ramasse le butin de pêche tout de suite, même si la fouille automatique du jeu est désactivée.",
	["Tramo %d de %d"] = "Tronçon %d sur %d",
	["Tramo %d de %d: %s."] = "Tronçon %d sur %d : %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Pièges, coups au corps à corps d'urgence et beaucoup d'agilité : le chasseur le plus difficile à attraper.",
	["Tranquilo"] = "Prudent",
	["Transformar"] = "Transformer",
	["Tu Grito de batalla llega a todo el grupo y dura más."] = "Votre Cri de guerre touche tout le groupe et dure plus longtemps.",
	["Tu abisario aguanta los golpes por ti: deja que empiece la pelea."] = "Votre marcheur du Vide encaisse les coups pour vous : laissez-le commencer le combat.",
	["Tu arma secundaria pega más."] = "Votre arme en main gauche frappe plus fort.",
	["Tu banco: en vivo si estás con un banquero, si no, la última foto."] = "Votre banque : en direct si vous êtes chez un banquier, sinon le dernier relevé.",
	["Tu botón de emergencia."] = "Votre bouton d'urgence.",
	["Tu buff"] = "Votre buff",
	["Tu build %s sugiere %s (rango %d). Escribe /alfa builds para aplicarlo con un clic."] = "Votre build %s suggère %s (rang %d). Tapez /alfa builds pour l'appliquer en un clic.",
	["Tu clase no necesita recordatorio"] = "Votre classe n'a pas besoin de rappel",
	["Tu clase no tiene habilidades de reacción que Alfa vigile."] = "Votre classe n'a pas de techniques de réaction surveillées par Alfa.",
	["Tu cliente no deja cambiar talentos desde un addon. Usa la ventana de talentos del juego (tecla N)."] = "Votre client ne permet pas à un addon de changer les talents. Utilisez la fenêtre des talents du jeu (touche N).",
	["Tu cliente no tiene la línea de tiempo de jefes."] = "Votre client n'a pas la chronologie des boss.",
	["Tu cliente no trae el resaltado oficial de botones: Alfa marca el botón con un borde."] = "Votre client n'a pas la surbrillance officielle des boutons : Alfa marque le bouton avec une bordure.",
	["Tu cliente no trae estas opciones. Si Blizzard las agrega, aparecerán aquí solas."] = "Votre client n'a pas ces options. Si Blizzard les ajoute, elles apparaîtront ici toutes seules.",
	["Tu cliente no trae la ayuda de combate de Blizzard."] = "Votre client n'a pas l'assistant de combat de Blizzard.",
	["Tu cliente trae el resaltado oficial de botones; Alfa lo deja en manos del juego."] = "Votre client a la surbrillance officielle des boutons ; Alfa laisse le jeu s'en charger.",
	["Tu demonio es más fuerte y tú más resistente: el brujo más seguro."] = "Votre démon est plus fort et vous plus résistant : le démoniste le plus sûr.",
	["Tu entrenador tiene algo nuevo para ti"] = "Votre maître a quelque chose de nouveau pour vous",
	["Tu entrenador: %s (%s)."] = "Votre maître : %s (%s).",
	["Tu entrenador: %s."] = "Votre maître : %s.",
	["Tu equipo se está gastando"] = "Votre équipement s'use",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "Votre coup le plus fort du niveau 40 au 60.",
	["Tu golpe más fuerte desde el nivel 40."] = "Votre coup le plus fort dès le niveau 40.",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "Votre coup le plus fort, il grandit avec votre blocage.",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "Votre coup le plus fort, qui réduit en plus les soins de l'ennemi.",
	["Tu golpe más fuerte."] = "Votre coup le plus fort.",
	["Tu golpe principal contra jefes."] = "Votre coup principal contre les boss.",
	["Tu golpe principal."] = "Votre coup principal.",
	["Tu grupo"] = "Votre groupe",
	["Tu grupo en el mapa y el minimapa, con el color de su clase."] = "Votre groupe sur la carte et la minicarte, aux couleurs de leur classe.",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "Votre groupe et votre raid avec leur vie, pour soigner en un clic. Se change hors combat.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "Votre guide est prêt. Ouvrez-le pour voir votre étape.",
	["Tu hermandad te ve en el mapa y te puede seguir. Se envía tu posición, nivel y clase cada 10 segundos mientras te mueves."] = "Votre guilde vous voit sur la carte et peut vous suivre. Votre position, votre niveau et votre classe sont envoyés toutes les 10 secondes quand vous bougez.",
	["Tu hermandad: quienes comparten su ubicación con Alfa."] = "Votre guilde : ceux qui partagent leur position avec Alfa.",
	["Tu libro no tiene hechizos para aliados"] = "Votre grimoire n'a pas de sorts pour les alliés",
	["Tu lista de sonidos"] = "Votre liste de sons",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "Votre liste de sons est vide. Ajoutez-en un avec /alfa silenciar <numéro>.",
	["Tu lista de sonidos quedó vacía."] = "Votre liste de sons est maintenant vide.",
	["Tu manada en el mapa: grupo, hermandad y amigos. Síguelos con la flecha y conoce al clan."] = "Votre meute sur la carte : groupe, guilde et amis. Suivez-les avec la flèche et découvrez le clan.",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "Votre configuration de souris est vide : choisissez d'abord quelque chose pour un emplacement.",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "Votre familier fait une grande partie du travail et encaisse les coups : la façon la plus facile et la plus sûre de monter un chasseur.",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Votre cible a esquivé : Fulgurance ne peut pas être esquivée et frappe fort. Nécessite la posture de combat.",
	["Tu personaje"] = "Votre personnage",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Votre personnage cesse de dire « Pas assez de mana », « Ce n'est pas encore prêt » et autres phrases du genre. Le texte rouge reste.",
	["Tu pesca está al máximo."] = "Votre pêche est au maximum.",
	["Tu posición en la parte de abajo del minimapa."] = "Votre position en bas de la minicarte.",
	["Tu posición y la del cursor bajo el mapa."] = "Votre position et celle du curseur sous la carte.",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "Votre première session entrera dans le journal quand vous quitterez le jeu. La meute vous attend : en chasse !",
	["Tu progreso se guarda por personaje; los ajustes, para toda la cuenta."] = "Votre progression est enregistrée par personnage ; les réglages, pour tout le compte.",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "Votre propre cadre s'affiche même si vous n'êtes pas en groupe, pour vous soigner en un clic.",
	["Tu ratón"] = "Votre souris",
	["Tu ritmo de los últimos 15 minutos, con el contador de XP de Alfa."] = "Votre rythme sur les 15 dernières minutes, avec le compteur d'XP d'Alfa.",
	["Tu ruta %s se actualizó."] = "Votre itinéraire %s a été mis à jour.",
	["Tu ruta está lista en el menú de guías, en Mis rutas."] = "Votre itinéraire est prêt dans le menu des guides, dans Mes itinéraires.",
	["Tu ruta está vacía. Agrega tramos (XP, oro, profesión, clase u objeto) o empieza con una plantilla."] = "Votre itinéraire est vide. Ajoutez des tronçons (XP, or, métier, classe ou objet) ou commencez avec un modèle.",
	["Tu ruta no tiene tramos todavía."] = "Votre itinéraire n'a pas encore de tronçons.",
	["Tu ruta personalizada, armada por Alfa con tus tramos."] = "Votre itinéraire personnalisé, construit par Alfa avec vos tronçons.",
	["Tu ruta, liberar misiones y el catálogo de objetos (/alfa rutas ayuda)."] = "Votre itinéraire, libérer des quêtes et le catalogue d'objets (/alfa rutas ayuda).",
	["Tu sesión anterior (%s): %s"] = "Votre session précédente (%s) : %s",
	["Tu sesión anterior, %s"] = "Votre session précédente, %s",
	["Tu sesión de ahora"] = "Votre session en cours",
	["Tu sesión, tus avisos y tu siguiente paso, de un vistazo."] = "Votre session, vos rappels et votre prochaine étape, en un coup d'œil.",
	["Tu siguiente paso"] = "Votre prochaine étape",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela abajo para pescar con una sola tecla."] = "Votre touche et vos réglages du jeu restent comme d'habitude. Activez-la plus bas pour pêcher avec une seule touche.",
	["Tu tramo de profesión ahora junta %s."] = "Votre tronçon de métier récolte maintenant %s.",
	["Tu ubicación"] = "Votre position",
	["Tu ubicación es privada: no la compartes con nadie."] = "Votre position est privée : vous ne la partagez avec personne.",
	["Tu ventana de bolsas de Alfa. También con la B."] = "Votre fenêtre de sacs Alfa. Aussi avec B.",
	["Tu zona: %s"] = "Votre zone : %s",
	["Tu zona: (desconocida)"] = "Votre zone : (inconnue)",
	["Tu árbol: un tramo después de otro"] = "Votre arbre : un tronçon après l'autre",
	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "Votre dernier scan : %s. Scannez à nouveau à l'hôtel des ventes pour avoir des prix à jour.",
	["Tus amigos con Alfa que te comparten su ubicación salen en tu mapa y los puedes seguir."] = "Vos amis avec Alfa qui partagent leur position avec vous apparaissent sur votre carte, et vous pouvez les suivre.",
	["Tus amigos que te comparten su ubicación."] = "Vos amis qui partagent leur position avec vous.",
	["Tus bolsas"] = "Vos sacs",
	["Tus bolsas están casi llenas"] = "Vos sacs sont presque pleins",
	["Tus bolsas están llenas"] = "Vos sacs sont pleins",
	["Tus bolsas están vacías."] = "Vos sacs sont vides.",
	["Tus bolsas y tu banco en una sola ventana, y lo que lleva cada uno de tus personajes."] = "Vos sacs et votre banque dans une seule fenêtre, et ce que porte chacun de vos personnages.",
	["Tus builds importados"] = "Vos builds importés",
	["Tus clics de Curación se aplican al salir de combate."] = "Vos clics de Soins s'appliqueront à la sortie du combat.",
	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "Vos clics reviennent à ceux du préréglage. Ce que vous avez changé à la main est perdu.",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Les membres de votre groupe et de votre raid sur la carte d'Alfa.",
	["Tus críticos de habilidades pegan todavía más."] = "Les critiques de vos techniques frappent encore plus fort.",
	["Tus críticos hacen muchísimo daño."] = "Vos critiques font énormément de dégâts.",
	["Tus críticos hacen sangrar: matas más rápido y sufres menos."] = "Vos critiques font saigner : vous tuez plus vite et souffrez moins.",
	["Tus críticos sangran."] = "Vos critiques font saigner.",
	["Tus críticos sangran: más daño y amenaza."] = "Vos critiques font saigner : plus de dégâts et de menace.",
	["Tus curas curan más."] = "Vos soins soignent davantage.",
	["Tus estadísticas"] = "Vos statistiques",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Vos coups touchent un second ennemi : parfait quand deux ennemis s'en prennent à vous.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Vos cris portent plus loin et durent plus longtemps : vous aidez tout le groupe.",
	["Tus habilidades cuestan menos ira."] = "Vos techniques coûtent moins de rage.",
	["Tus habilidades de ira te curan: menos descanso."] = "Vos techniques de rage vous soignent : moins de repos.",
	["Tus hechizos de daño pegan más."] = "Vos sorts de dégâts frappent plus fort.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "Vos sorts de givre ralentissent : le monstre n'arrive presque jamais à vous frapper.",
	["Tus hechizos fallan menos."] = "Vos sorts ratent moins.",
	["Tus hechizos hacen crítico más seguido."] = "Vos sorts font plus souvent des critiques.",
	["Tus llaves junto a tus bolsas."] = "Vos clés à côté de vos sacs.",
	["Tus misiones abiertas"] = "Vos quêtes en cours",
	["Tus personajes"] = "Vos personnages",
	["Tus próximos talentos"] = "Vos prochains talents",
	["Tus puntos van en %s"] = "Vos points sont dans %s",
