	["Ubicación de %s"] = "Position de %s",
	["Un /reload no la corta."] = "Un /reload ne l'interrompt pas.",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "Une arme dans chaque main et beaucoup de rage : celui qui fait le plus de dégâts en groupe.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Une grande arme à deux mains et des coups qui font saigner. La façon la plus facile de monter.",
	["Un aturdimiento cuando lo necesites."] = "Un étourdissement quand vous en avez besoin.",
	["Un aviso grande cuando una habilidad que depende de lo que pasó se activa (por ejemplo, Abrumar después de que el enemigo esquive)."] = "Une grande alerte quand une technique qui dépend de ce qui vient de se passer devient utilisable (par exemple, Fulgurance après une esquive de l'ennemi).",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Une bordure de la couleur de la qualité : vert, bleu, violet...",
	["Un borde en el botón de tu barra que tiene la sugerencia, para que lo encuentres rápido."] = "Une bordure sur le bouton de votre barre qui contient la suggestion, pour le trouver vite.",
	["Un clic y queda solo lo esencial: tú, tu grupo y el siguiente paso de la guía."] = "Un clic et il ne reste que l'essentiel : vous, votre groupe et l'étape suivante du guide.",
	["Un cuadro pequeño con tu vida y las estadísticas más importantes de tu build. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Un petit cadre avec votre vie et les statistiques les plus importantes de votre build. En combat, le jeu masque certains chiffres : le dernier lisible reste affiché.",
	["Un fondo del color de tu clase bajo tu nombre."] = "Un fond de la couleur de votre classe sous votre nom.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Un énorme coup de bouclier et énormément de menace.",
	["Un golpe más para gastar ira."] = "Un coup de plus pour dépenser la rage.",
	["Un golpe nuevo y fuerte para tu barra."] = "Un nouveau coup puissant pour votre barre.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Un gros bonus de dégâts pour les monstres difficiles ; il vous libère aussi de la peur.",
	["Un mapa limpio con un solo control para todo lo que se pinta."] = "Une carte épurée avec une seule commande pour tout ce qui s'y affiche.",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Un cadre doré sur ce qui sert à une quête (avec « ! » si l'objet en commence une).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo."] = "Un objet que vous voulez : Alfa trace le chemin pour l'obtenir.",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Un petit repère numéroté là où vous mènent les prochaines étapes.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Un peu de coup critique, d'esquive et d'armure.",
	["Un poco de vida de vuelta después de críticos."] = "Un peu de vie récupérée après les critiques.",
	["Un poco más de defensa."] = "Un peu plus de défense.",
	["Un poco más de ira al cargar."] = "Un peu plus de rage en chargeant.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Un point pour ouvrir la rangée suivante et rater un peu moins.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Un point d'exclamation au-dessus de ceux qui donnent des quêtes de votre niveau.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Un point d'interrogation au-dessus de ceux qui attendent une quête terminée.",
	["Un solo mapa continuo: acerca, aleja y pasa de una zona a otra sin cambiar de mapa."] = "Une seule carte continue : zoomez, dézoomez et passez d'une zone à l'autre sans changer de carte.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Un tank qui frappe fort : beaucoup de menace pour les groupes qui font beaucoup de dégâts, en échange de moins de défense en plus. Pour les tanks qui ont un peu d'expérience.",
	["Un ícono con el siguiente hechizo que recomienda la ayuda de combate oficial de Blizzard. Es solo una ayuda: tú decides qué apretar."] = "Une icône avec le prochain sort recommandé par l'assistant de combat officiel de Blizzard. Ce n'est qu'une aide : c'est vous qui décidez sur quoi appuyer.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Une barre avec les attaques que le boss va lancer et le temps restant avant chacune. Vous savez ainsi quand bouger ou vous défendre.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Une flèche verte sur l'équipement meilleur que celui que vous portez, selon votre classe et votre niveau.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Une bande vert clair montre les soins déjà en route.",
